/**
 * demo.ts
 *
 * Baked-in sample traces so the app renders something the moment it loads,
 * with no upload. Each demo is a small pre-scoped slice (one city, one date
 * window) stored in public/demo/{id}.json — a few hundred points, ~50KB.
 *
 * Generated by scripts/extract-demo.mjs from a Google Timeline export.
 * Overnight dwell points are stripped at extraction time: they are stationary,
 * so they add a hotspot rather than a route, and they are the most identifying
 * points in the file.
 */

import type { TracePoint } from './parseTimeline'
import { CITIES, type CityMeta } from './cities'

export interface DemoSet {
  id: string
  /** Must match a city id in CITIES — decides which street network loads. */
  cityId: string
  label: string
  /** Short human description of the trip, shown in the demo bar. */
  blurb: string
}

export const DEMOS: DemoSet[] = [
  {
    id: 'buenos-aires',
    cityId: 'buenos-aires',
    label: 'Buenos Aires',
    blurb: 'Nine days, September 2025',
  },
  {
    id: 'sao-paulo',
    cityId: 'sao-paulo',
    label: 'São Paulo',
    blurb: 'Seven days, October 2025',
  },
]

export const DEFAULT_DEMO = DEMOS[0]

interface DemoFile {
  city: string
  label: string
  points: { lat: number; lng: number; timestamp: string; source: 'path' | 'visit' }[]
}

export function demoCity(demo: DemoSet): CityMeta | null {
  return CITIES.find(c => c.id === demo.cityId) ?? null
}

/** Fetch and hydrate a demo trace. Throws on a missing or malformed file. */
export async function loadDemo(demo: DemoSet): Promise<TracePoint[]> {
  const res = await fetch(`/demo/${demo.id}.json`)
  if (!res.ok) throw new Error(`Sample data for ${demo.label} is unavailable.`)
  const data = await res.json() as DemoFile
  if (!Array.isArray(data.points) || data.points.length === 0) {
    throw new Error(`Sample data for ${demo.label} is empty.`)
  }
  return data.points.map(p => ({
    lat: p.lat,
    lng: p.lng,
    timestamp: new Date(p.timestamp),
    source: p.source,
  }))
}
